<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/crypto.php';$merchant=require_login();$pageTitle='Multi-Accounts';$pdo=db();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='toggle'){$q=$pdo->prepare('UPDATE merchant_accounts SET is_active=IF(is_active=1,0,1) WHERE id=? AND merchant_id=?');$q->execute([(int)$_POST['id'],$merchant['id']]);$notice='Account state updated.';}elseif(($_POST['action']??'')==='add'){$label=trim((string)($_POST['account_label']??''));$upi=trim((string)($_POST['upi_id']??''));$email=filter_var($_POST['linked_email']??'',FILTER_VALIDATE_EMAIL);$pass=preg_replace('/\s+/','',(string)($_POST['app_password']??''));if($label===''||!preg_match('/^[A-Za-z0-9._-]{2,128}@[A-Za-z0-9.-]{3,190}$/',$upi)||!$email||!preg_match('/^[A-Za-z0-9]{16}$/',$pass))$notice='Provide a valid label, UPI ID, email and 16-character app password.';else{$q=$pdo->prepare('INSERT INTO merchant_accounts(merchant_id,account_label,upi_id,linked_email,google_app_password,is_active) VALUES(?,?,?,?,?,0)');$q->execute([$merchant['id'],substr($label,0,100),$upi,$email,encrypt_secret($pass)]);$notice='Standby account added. Activate it only after validating provider setup.';}}}$q=$pdo->prepare('SELECT id,account_label,upi_id,linked_email,is_active,last_checked_at FROM merchant_accounts WHERE merchant_id=? ORDER BY id');$q->execute([$merchant['id']]);$accounts=$q->fetchAll();require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title"><div><h1>Multi-accounts</h1><p>Keep independently configured receiving accounts organized.</p></div><span class="badge badge-blue">Account routing</span></div><div class="note">Additional accounts are for legitimate operational continuity. This tool does not increase, remove, or bypass any UPI provider or bank limits. Confirm each account is permitted for your business and configure receipt parsing before activating it. Order routing currently selects the first active account.</div><?php if($notice):?><div class="note panel"><?=h($notice)?></div><?php endif?><div class="card panel"><div class="card-title"><h3>Configured accounts</h3><span style="font-size:10px;color:var(--muted)"><?=count($accounts)?> accounts</span></div><div class="table-wrap"><table><thead><tr><th>ACCOUNT</th><th>UPI ID</th><th>RECEIPT EMAIL</th><th>STATE</th><th>ACTION</th></tr></thead><tbody><?php if(!$accounts):?><tr><td colspan="5" style="text-align:center;padding:24px;color:var(--muted)">No receiving accounts yet.</td></tr><?php endif?><?php foreach($accounts as $a):?><tr><td><strong><?=h($a['account_label'])?></strong></td><td><?=h($a['upi_id'])?></td><td><?=h($a['linked_email'])?></td><td><span class="badge <?=$a['is_active']?'badge-success':'badge-pending'?>"><?=$a['is_active']?'Active':'Standby'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=h((string)$a['id'])?>"><button class="btn btn-outline" style="padding:5px 9px"><?=$a['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></tbody></table></div></div><div class="card panel"><div class="card-title"><h3>Add a standby account</h3></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="field"><label>Account label</label><input name="account_label" required placeholder="Secondary account"></div><div class="field"><label>UPI ID</label><input name="upi_id" required placeholder="name@bank"></div><div class="field"><label>Receipt email</label><input type="email" name="linked_email" required></div><div class="field"><label>Google app password</label><input type="password" name="app_password" required autocomplete="new-password"></div><div class="field full"><button class="btn">Add standby account</button></div></form></div><?php require __DIR__.'/includes/dashboard-footer.php';?>